                un valor positivo, comprendido entre 100 y 999,99');
                
            }
        let ley1 = redondeo2(ley0 -5);                              //se calcula la ley recuperable restando 5 puntos 
        frm.set_value('ley_recuperable', ley1);                     //se establece el valor de la ley recuperable en el campo correspondiente
	    let descuento_viruta = frm.doc.descuento_viruta;
