function redondeo2(num, decimalPlaces = 2) {
    var p = Math.pow(10, decimalPlaces);
    var n = (num * p) * (1 + Number.EPSILON);
    return Math.round(n) / p;
}

// Función reutilizable para calcular factor de comisión
function calcularFactor(frm) {
    if (frm.doc.comision_cobrada === 1) {
        return -1;
    } else if (frm.doc.comision_pagada === 1) {
        return 1;
    } else {
        return 0;
    }
}

// Función reutilizable para calcular los valores relacionados con la comisión y el total
function actualizarValores(frm, factor) {
    let d = frm.doc;
    let total = d.total_neto;
    let comision_porcentual = total === 0 ? 0 : redondeo2(d.comision * 100 / total);
    frm.set_value("comision_porcentual", comision_porcentual);
    
    let total_pagar = total + (factor * d.comision);
    frm.set_value("total_pagar", total_pagar);
    
    let total_pagado = d.total_pagado;
    frm.set_value("queda_por_pagar", total_pagar - total_pagado);
}

frappe.ui.form.on('Cambios', {
    
    onload(frm) {
        const applyFilter = (field, fieldname, queryFunc) => {
            frm.set_query(field, fieldname, queryFunc);  // Aquí pasamos los tres argumentos correctos
        };
        
        // Aplicamos el filtro a 'cuenta_de_ingreso' en la tabla 'items'
        applyFilter('cuenta_de_ingreso', 'pagos_in', function(doc, cdt, cdn) {
            let d = locals[cdt][cdn];
            let divisa = d.divisa_de_cambio;
            let ofic = frm.doc.acronimo_oficina;
        
            // Si 'divisa' es null o undefined, usa '%'
            if (!divisa) {
                divisa = '%';
            }
        
            return {
                'filters': [
                    ['Mode of Payment', 'mode_of_payment', 'like', '%(' + divisa + ')%'],
                    ['Mode of Payment', 'mode_of_payment', 'like', '%' + ofic + '%'],
                ],
            };
        });


        applyFilter('destino_de_pago', 'pagos_out', (doc, cdt, cdn) => {
            let d = locals[cdt][cdn];
            let regex = new RegExp('\\(([^()]*[^()]*)\\)', 'g');
            let filtro = 'efectivo';
            let regex2 = new RegExp(filtro, 'i');
            let str = d.modo_de_pago;
            let cuenta = null;
            let persona = frm.doc.supplier;

            if (regex2.test(str)) {
                cuenta = regex.exec(str) || ['%', '%'];
                return {
                    'filters': [['Bank Account', 'account_name', 'like', '%' + filtro + '%']],
                };
            } else {
                cuenta = regex.exec(str) || ['%', '%'];
                return {
                    'filters': [
                        ['Bank Account', 'account_name', 'like', '%' + cuenta[0] + '%'],
                        ['Bank Account', 'party', 'like', '%' + persona + '%'],
                    ],
                };
            }
        });

        applyFilter('persona', (doc) => {
            let filtro = doc.supplier || 'Seleccione Cliente';
            return {
                'filters': [['Dynamic Link', 'link_name', 'like', '%' + filtro + '%']],
            };
        });
