        let factor = calcularFactor(frm);
        actualizarValores(frm, factor);
    },

    comision_cobrada(frm) {
        let factor = calcularFactor(frm);
        actualizarValores(frm, factor);
    },

    comision_pagada(frm) {
        let factor = calcularFactor(frm);
        actualizarValores(frm, factor);
