function redondeo2(num, decimalPlaces = 2) //funcion de apoyo para optimizar los calculos
{
    var p = Math.pow(10, decimalPlaces);
    var n = (num * p) * (1 + Number.EPSILON);
    return Math.round(n) / p;
}

