                                ]
                },
                callback: function(r) {
                    if (r.message) {
                        frm.set_value('viruta_disponible', r.message.actual_qty);
                        frm.set_value('valoracion_total', (r.message.valuation_rate)*(r.message.actual_qty));
                        frm.set_value('valoracion_unitaria', r.message.valuation_rate);
                    }
                }
        });
    },

    calcular: function(frm){
        let peso0 = frm.doc.viruta_disponible;
        let peso1 = frm.doc.peso_fundido;
        let merma = 0;
        let ley0 = frm.doc.ley_analitica;
        let ley1 = 0;
        let puras = 0;
        let valoracion_total = frm.doc.valoracion_total;
        let valoracion_puras = 0;

        merma = redondeo2(((peso1-peso0)/peso0)*100);
        if(merma > 0)
        {
            frappe.throw(
                'No es posible obtener una Merma positiva de :  '+ merma + '% Verifique los datos vuelva a calcular'
            );
        }

        ley1 = (ley0-5);

        if(ley0 > 999.99 || ley0 < 0 || ley0 < 100)         //condicion para evitar que se coloque un valor de ley incorrecto.
            {

            frm.set_value('ley_analitica', 0);              //reestrablecer valor de la ley
            frm.set_value('ley_recuperable', 0);            //reestablecer ley recuperable
            frappe.throw(
                'verifique el valor correspondiente la ley no puede ser '+ley0+' la ley debe ser \
                un valor positivo, comprendido entre 100 y 999,99');

            }
        puras = redondeo2((peso1*ley1)/1000);
        valoracion_puras = redondeo2((valoracion_total/puras));
        frm.set_value('puras', puras);
        frm.set_value('merma_porc', merma);
        frm.set_value('ley_recuperable', ley1);
        frm.set_value('valoracion_unitaria_puras',valoracion_puras);

    }
});

