// Definir la función para ocultar/mostrar campos
function toggle_elementos(frm) {
    // Arrays con nombres de campos y secciones
    let campos = [  'supplier_invoice_details', 'scan_barcode', 'rejected_warehouse', 
                    'is_subcontracted', 'taxes_section', 'section_break_51', 'section_break_44',
                    'raw_materials_supplied', 'tax_withholding_net_total', 'base_tax_withholding_net_total',
                    'totals'
                ];
    let secciones = ['payments_tab', 'terms_tab'];

    // Verificar el valor de custom_es_orokalipso
    if (frm.doc.custom_es_orokalipso == 1) {
        // Ocultar los campos
        campos.forEach(function(campo) {
            frm.toggle_display(campo, false);
        });

        // Ocultar las secciones
        secciones.forEach(function(seccion) {
            $(`[data-fieldname="${seccion}"]`).hide();
        });

    } else {
        // Mostrar los campos
        campos.forEach(function(campo) {
            frm.toggle_display(campo, true);
        });

        // Mostrar las secciones
        secciones.forEach(function(seccion) {
            $(`[data-fieldname="${seccion}"]`).show();
        });
    }
}
//fin definir campos para ocultar


