            cantidad_puras += 1;
            total_peso_puras += item.peso_fundido;
            total_puras += item.puras;
            valoracion_puras += item.valoracion_total_puro;
        }
    });
    //calculo de valores a asignar
    cantidad_piezas_procesadas = (cantidad_puras + cantidad_amalgamado);
    peso_total_procesado = redondeo2(total_peso_puras + total_peso_amalgamado);
    puras_total_procesadas = redondeo2(total_puras);
    ley_recuperable_promedio = redondeo2((puras_total_procesadas/peso_total_procesado)*1000);

    let almacen_sistema = '';
    let item_sistema = '';
    let valoracion_unitaria_sistema = 0;

