//Funcion para calcular puras y ley recuperable
function calcular_puras_y_ley_recuperable(frm, cdt, cdn) {
    // Obtener la fila actual que se está editando
    let fila = locals[cdt][cdn];

    if (fila.peso_fundido && fila.ley_analitica) {
        // Realizar el cálculo de 'puras' y 'ley_recuperable'
        fila.ley_recuperable = redondeo2(fila.ley_analitica - 5); // Ajusta la lógica de cálculo según lo que necesites
        fila.puras = redondeo2((fila.peso_fundido * fila.ley_recuperable)/1000);

        // Refrescar la fila editada: al actualizar un campo específico, este se reflejará en la interfaz del usuario
        frm.refresh_field('piezas_out'); // Refrescar la tabla hija completa para ver los cambios
        // Calcular valores acumulados para los campos del formulario principal
        actualizar_campos_padre(frm);
    }
}
