    }

    // Realizar los cálculos adicionales para los otros campos
    let ley_resultante = peso_resultante > 0 ? redondeo2((puras_resultantes / peso_resultante) * 1000) : 0;
    let diferencia_de_peso = peso_resultante - frm.doc.peso_total_procesado;
    let diferencia_puras = puras_resultantes - frm.doc.puras_total_procesadas;
    let merma_peso_porc = frm.doc.peso_total_procesado !== 0 ? redondeo2((diferencia_de_peso / frm.doc.peso_total_procesado) * 100) : 0;
    let merma_puras_porc = frm.doc.puras_total_procesadas !== 0 ? redondeo2((diferencia_puras / frm.doc.puras_total_procesadas) * 100) : 0;
    let valoracion_total_resultante = frm.doc.valoracion_total;
    let valoracion_unitaria_resultante = puras_resultantes ? redondeo2(valoracion_total_resultante / puras_resultantes) : 0;

    // Actualizar los campos del formulario padre
    frm.set_value('peso_resultante', redondeo2(peso_resultante));
    frm.set_value('puras_resultantes', redondeo2(puras_resultantes));
    frm.set_value('ley_resultante', ley_resultante);
    frm.set_value('diferencia_de_peso', redondeo2(diferencia_de_peso));
    frm.set_value('diferencia_puras', redondeo2(diferencia_puras));
    frm.set_value('merma_peso_porc', merma_peso_porc);
    frm.set_value('merma_puras_porc', merma_puras_porc);
    frm.set_value('valoracion_total_resultante', valoracion_total_resultante);
