    } else if (tipoArticulo.includes("amalgamado")) {
        fieldnames = ['item_amalgamado', 'almacen_de_oro_amalgamado'];
    } else if (tipoArticulo.includes("prenda")) {
        fieldnames = ['item_prendas', 'almacen_de_oro_prendas'];
    }

    frappe.call({
        method: "frappe.client.get_value",
        args: {
            doctype: "Oficinas configuraciones",
            filters: {
                name: oficina
            },
            fieldname: fieldnames
        },
        callback: function(r) {
            if (r.message) {
                almacen_sistema = r.message[fieldnames[1]];
                item_sistema = r.message[fieldnames[0]];

                if (almacen_sistema && item_sistema) {
                    // Obtener la tasa de valoración desde el Doctype 'Bin'
                    frappe.call({
                        method: 'frappe.client.get_value',
                        args: {
                            doctype: 'Bin',
                            filters: {
                                item_code: item_sistema,
                                warehouse: almacen_sistema
                            },
                            fieldname: 'valuation_rate'
                        },
                        callback: function(r) {
                            if (r.message) {
                                // Asignar la tasa de valoración del producto específico en el almacén
                                valoracion_unitaria_sistema = r.message.valuation_rate;
                                valoracion_total = (valoracion_puras + valoracion_amalgamado);

                                let valoracion_total_sistema = 0;
                                if (total_puras > 0) {
                                    valoracion_unitaria = redondeo2(valoracion_total / puras_total_procesadas);
                                    valoracion_total_sistema = redondeo2(valoracion_unitaria_sistema * puras_total_procesadas);
                                } else {
                                    valoracion_unitaria = redondeo2(valoracion_total / peso_total_procesado);
                                    valoracion_total_sistema = redondeo2(valoracion_unitaria_sistema * peso_total_procesado);
                                }

                                // Asignar valores al formulario
                                frm.set_value('custom_cantidad_de_piezas', cantidad_piezas_procesadas);
                                frm.set_value('custom_peso_total_procesado', peso_total_procesado);
                                frm.set_value('custom_puras_total_procesadas', puras_total_procesadas);
                                frm.set_value('custom_valoracion_unitaria_piezas', valoracion_unitaria);
                                frm.set_value('custom_valoracion_total_piezas', valoracion_total);
                                frm.set_value('custom_valoracion_unitaria_sistema', valoracion_unitaria_sistema);
                                frm.set_value('custom_valoracion_total_sistema', valoracion_total_sistema);
                                frm.set_value('custom_ley_recuperable_promedio', ley_recuperable_promedio);
                            } else {
                                frappe.msgprint(__('No se encontró una tasa de valoración para el producto en el almacén seleccionado.'));
                            }
                        }
                    });
                } else {
                    frappe.msgprint(__('Por favor, seleccione un almacén y un producto válidos.'));
                }
            } else {
                frappe.throw('Error De Configuracion');
            }
        }
    });
}
//fin de la funcion

//Funcion para ocultar elementos distractores
function toggle_elementos(frm) {
    // Arrays con nombres de campos y secciones
    let campos = [
        'scan_barcode', 'taxes_section', 'section_break_40', 'section_break_43', 'section_break_49', 'sec_tax_breakup',
        'pricing_rule_details', 'packing_list', 'time_sheet_list', 'section_break_104', 'is_pos', 'is_consolidated', 'is_return',
        'is_debit_note'
    ];
    let secciones = ['payments_tab', 'terms_tab', ];

    // Verificar el valor de custom_es_orokalipso
    if (frm.doc.custom_es_orokalipso == 1) {
        // Ocultar los campos
        campos.forEach(function(campo) {
            frm.toggle_display(campo, false);
        });

        // Ocultar las secciones
        secciones.forEach(function(seccion) {
            $(`[data-fieldname="${seccion}"]`).hide();
        });

    } else {
        // Mostrar los campos
        campos.forEach(function(campo) {
            frm.toggle_display(campo, true);
        });

        // Mostrar las secciones
        secciones.forEach(function(seccion) {
            $(`[data-fieldname="${seccion}"]`).show();
        });
    }
}
//fin de funcion de ocultar 

//funcionamiento del documento 
frappe.ui.form.on('Sales Invoice', {
    validate: function(frm) {
        // Verificar que la tabla 'items' tenga solo una fila
        if (frm.doc.items.length !== 1) {
            frappe.throw(__('La tabla "items" debe contener exactamente una fila.'));
        }

        // Obtener el tipo de artículo y la única fila de la tabla 'items'
        let tipoArticulo = frm.doc.custom_tipo_articulo ? frm.doc.custom_tipo_articulo.toLowerCase() : '';
        let itemRow = frm.doc.items[0];
        let qtyEsperado = 0;

        // Determinar el valor esperado de 'qty' según el tipo de artículo
        if (tipoArticulo.includes('amalgamado')) {
            qtyEsperado = frm.doc.custom_peso_total_procesado || 0;
        } else if (tipoArticulo.includes('puro') || tipoArticulo.includes('prenda')) {
            qtyEsperado = frm.doc.custom_puras_total_procesadas || 0;
        } else {
            frappe.throw(__('El tipo de artículo no es válido o no está configurado.'));
        }

        // Verificar que 'qty' coincida con el valor esperado
        if (itemRow.qty !== qtyEsperado) {
            frappe.throw(__('La cantidad en la tabla "items" debe ser igual a {0}. Actualmente es {1}.', [qtyEsperado, itemRow.qty]));
        }
    },

    custom_obtener_piezas: function(frm) {
        let oficina = frm.doc.custom_oficina;
        let tipo_articulo = frm.doc.custom_tipo_articulo;
        if(!tipo_articulo){
            frappe.throw(__('El campo "Tipo de Articulo" no puede estar Vacio'));
        }

        if(!oficina){
            frappe.throw(__('El campo "Oficina" no puede estar Vacio'));
        }
        // Llamada al servidor para obtener las piezas disponibles según los criterios del campo "oficina" y "estatus_articulo"
        frappe.call({
            method: 'frappe.client.get_list',
            args: {
                doctype: 'Inventario Orokalipso',  // Cambia 'Inventario Orokalipso' por el nombre de tu Doctype que contiene las piezas
                filters: {
                            oficina: oficina,  // Filtra según el valor del campo "oficina" en el formulario
                            estatus_articulo: 'Disponible',  // Filtra para que solo obtenga artículos disponibles
                            docstatus: 1,
                            tipo_articulo: tipo_articulo
                },
                fields: [
                    'name',
                    'tipo_articulo',
                    'peso_fundido',
                    'ley_analitica',
                    'ley_recuperable',
                    'puras',
                    'valoracion_unitaria_puro',
                    'valoracion_total_puro',
                    'item_puro',
                    'almacen_destino_puro',
                    'peso_amalgamado',
                    'valoracion_unitaria_amalgamado',
                    'valoracion_total_amalgamado',
                    'articulo_de_oro_amalgamado',
                    'almacen_destino_amalgamado'
                ]  // Especifica los campos que necesitas
            },
            callback: function(r) {
                if (r.message && r.message.length > 0) {
                    // Limpiar la tabla hija antes de agregar nuevas filas
                    frm.clear_table('custom_piezas');

                    // Iterar sobre las piezas encontradas y agregarlas a la tabla hija
                    r.message.forEach(function(pieza) {
                        let row = frm.add_child('custom_piezas');
                        row.pieza_de_inventario = pieza.name;  // Asigna el ID o nombre de la pieza
                        row.tipo_articulo = pieza.tipo_articulo;
                        row.peso_fundido = pieza.peso_fundido;
                        row.ley_analitica = pieza.ley_analitica;
                        row.ley_recuperable = pieza.ley_recuperable;
                        row.puras = pieza.puras;
                        row.valoracion_unitaria_puro = pieza.valoracion_unitaria_puro;
                        row.valoracion_total_puro = pieza.valoracion_total_puro;
                        row.item_puro = pieza.item_puro;
                        row.almacen_destino_puro = pieza.almacen_destino_puro;
                        row.peso_amalgamado = pieza.peso_amalgamado;
                        row.valoracion_unitaria_amalgamado = pieza.valoracion_unitaria_amalgamado;
                        row.valoracion_total_amalgamado = pieza.valoracion_total_amalgamado;
                        row.articulo_de_oro_amalgamado = pieza.articulo_de_oro_amalgamado;
                        row.almacen_destino_amalgamado = pieza.almacen_destino_amalgamado;
                    });

                    // Refrescar la tabla hija para mostrar los cambios
                    frm.refresh_field('custom_piezas');

                    actualizar_totales(frm);
                } else {
                    frappe.msgprint(__('No se encontraron piezas disponibles para los criterios seleccionados.'));
                }
            },
            error: function(err) {
                frappe.msgprint(__('Hubo un error al obtener las piezas: ') + err.message);
            }
        });
    },

    custom_es_orokalipso: function(frm) {
        toggle_elementos(frm);
        if (frm.doc.custom_es_orokalipso == 1){
            frm.set_value("update_stock", 1);
        }else{
            frm.set_value("update_stock", 0);
        }
    },

    custom_tipo_articulo: function(frm) {
        let tipo_articulo = frm.doc.custom_tipo_articulo;
        let oficina = frm.doc.custom_oficina;
        let fieldname;

        if (tipo_articulo == 'Oro Puro') {
            fieldname = 'almacen_de_oro_puro';

        } else if (tipo_articulo == 'Oro Amalgamado') {
            fieldname = 'almacen_de_oro_amalgamado';

        } else {
            fieldname = 'almacen_de_oro_prendas';

        }

        frappe.call({
            method: "frappe.client.get_value",
            args: {
                doctype: "Oficinas configuraciones",
                filters: {
                    name: oficina
                },
                fieldname: fieldname
            },
            callback: function(r) {
                if (r.message && r.message[fieldname]) {
                    frappe.run_serially([
                        () => frm.set_value("set_warehouse", r.message[fieldname])
                    ]);
                } else {
                    frappe.throw('Error De Configuracion');
                }
            },
        });
    },

	custom_oficina: function(frm) {
	    let oficina = frm.doc.custom_oficina;
        frappe.call({
            method: 'frappe.client.get_value',
            args: {
                doctype: "Oficinas configuraciones",
                filters: {
                    name: oficina
                },
                fieldname: ['item_amalgamado',
                            'item_puro',
                            'item_prendas'
                ]
            },
          callback: function(r) {
            if (r.message) {
              // Extrae los artículos específicos del documento "Oficinas Configuraciones"
              const articulosPermitidos = [
                    r.message.item_amalgamado,
                    r.message.item_puro,
                    r.message.item_prendas
              ];
              // Aplica el filtro al campo 'custom_articulo_de_compra'
              frm.set_query('item_code', 'items',  function(doc, cdt, cdn) {
                return {
                  filters: [
                    ['Item', 'name', 'in', articulosPermitidos]
                  ]
                };
              });
            }
          }
        });
        frappe.call({
            method: "frappe.client.get_value",
            args: {
                doctype: "Oficinas configuraciones",
                filters: {
                    name: oficina
                },
                fieldname: ['acronimo',
                            'centro_costos_oro'
                            ]
            },
            callback: function(r) {
                if (r.message) {
                    frappe.run_serially([
                        //() => frm.set_value("custom_acronimo", r.message.acronimo),
                        () => frm.set_value("cost_center", r.message.centro_costos_oro),
                    ]);
                }else {frappe.throw('Error De Configuracion');}
            },
        });
	},

    custom_establecer: function(frm) {
        // Define los valores dinámicos para 'item_code'
        let tipoArticulo = frm.doc.custom_tipo_articulo ? frm.doc.custom_tipo_articulo.toLowerCase() : '';
        let fieldname = '';
        let oficina = frm.doc.custom_oficina;  // Ajusta el campo de oficina según corresponda

        // Determinar el campo de configuración según el tipo de artículo
        if (tipoArticulo.includes('amalgamado')) {
            fieldname = 'item_amalgamado';
        } else if (tipoArticulo.includes('puro')) {
            fieldname = 'item_puro';
        } else if (tipoArticulo.includes('prenda')) {
            fieldname = 'item_prendas';
        }

        // Verificar si el campo de oficina y fieldname están definidos
        if (!fieldname || !oficina) {
            frappe.msgprint(__('No se pudo determinar el artículo o la oficina. Verifica los datos.'));
            return;
        }

        // Obtener el código del artículo desde 'Oficinas configuraciones'
        frappe.call({
            method: "frappe.client.get_value",
            args: {
                doctype: "Oficinas configuraciones",
                filters: {
                    name: oficina
                },
                fieldname: fieldname
            },
            callback: function(r) {
                if (r.message && r.message[fieldname]) {
                    let item_code = r.message[fieldname];
                    let itemUpdated = false;

                    // Verificar si ya existe una fila con el item_code
                    frm.doc.items.forEach(function(row) {
                        if (row.item_code === item_code) {
                            itemUpdated = true;

                            // Actualizar la cantidad según el tipo de artículo
                            if (tipoArticulo.includes('amalgamado')) {
                                row.qty = frm.doc.custom_peso_total_procesado || 0;
                            } else if (tipoArticulo.includes('puro') || tipoArticulo.includes('prenda')) {
                                row.qty = frm.doc.custom_puras_total_procesadas || 0;
                            }

                            frappe.msgprint(__('Cantidad actualizada para el artículo {0}.', [item_code]));
                        }
                    });

                    // Si no se encontró una fila con el item_code, aplicar el filtro
                    if (!itemUpdated) {
                        frm.set_query('item_code', 'items', function() {
                            return {
                                filters: {
                                    item_code: item_code
                                }
                            };
                        });

                        frappe.msgprint(__('Filtro aplicado para el artículo {0}.', [item_code]));
                    }

                    // Refrescar la tabla para reflejar los cambios
                    frm.refresh_field('items');
                } else {
                    frappe.msgprint(__('No se encontró el artículo para la configuración especificada.'));
                }
            }
        });
    },
});



