frappe.listview_settings['Inventario Orokalipso'] = {
    onload: function(listview) {
        // Agregar un botón dentro de la barra de herramientas
        listview.page.add_inner_button(__('Cambiar Estado'), async function() {
            // Obtener los documentos seleccionados
            const selected_docs = listview.get_checked_items();

            if (selected_docs.length === 0) {
                frappe.msgprint(__('Por favor, selecciona al menos un documento.'));
                return;
            }

            // Confirmar la acción con el usuario
            const confirmed = await frappe.confirm(__('¿Estás seguro de que deseas cambiar el estado de los documentos seleccionados a "Vendido"?'));
            if (!confirmed) return;

            // Iterar sobre los documentos seleccionados y actualizar el estado
            for (const doc of selected_docs) {
                try {
                    await frappe.db.set_value('Inventario Orokalipso', doc.name, 'estatus_articulo', 'Vendido');
                    frappe.show_alert({
                        message: `Estado actualizado para ${doc.name}`,
                        indicator: 'green'
                    });
                } catch (err) {
                    // Manejar correctamente el mensaje de error
                    let error_message = err.message || JSON.stringify(err);
                    frappe.msgprint(`Error al actualizar el estado para ${doc.name}: ${error_message}`);
                }
            }

            // Refrescar la vista de lista
            listview.refresh();
        });
    }
};
